import multiprocessing # For multiprocessing.Queue and Connection type hints if specific

# Assuming helpers and context are in the same package directory for relative imports
from .local_parallelization_helpers import _set_cpu_affinity, _generic_task_wrapper

# --- Module Overview ---
# This module provides a collection of wrapper functions essential for executing target functions
# within separate processes managed by the `LocalParallelizationManager`. These wrappers standardize
# the execution environment and ensure consistent interaction patterns with the manager.
#
# Key responsibilities and features of the wrappers:
# - CPU Affinity: Setting CPU affinity for the new process, if a core is assigned (delegated to
#   `_set_cpu_affinity` from `local_parallelization_helpers.py`).
# - Context Instantiation: For main "ParaProc" functions, the `LocalParallelizationProcessWrapper`
#   instantiates and injects a `ParallelizationManagerContext` object, enabling the ParaProc
#   to communicate with the manager.
# - Standardized Execution and Error Handling: Most task-specific wrappers (`_simple_private_task_wrapper`,
#   `_group_member_task_wrapper`, `ManagedSharedProcessWrapper`) utilize the `_generic_task_wrapper`
#   (from `local_parallelization_helpers.py`). This generic wrapper executes the target function,
#   catches exceptions, and formats the outcome (success result or exception details).
# - Result/Error Reporting: The formatted outcome is sent back to the `LocalParallelizationManager`
#   over a dedicated `multiprocessing.Connection`. This standardized reporting mechanism is crucial
#   for the manager to process task completions and for the `ParallelizationManagerContext` methods
#   to ultimately provide their consistent `(Success, ID, Response/Error)` tuple to the calling ParaProc.
# - Unique ID Propagation: Wrappers receive and include relevant unique IDs (SPRV-ID, GPRV-ID, task names)
#   in the data sent back to the manager, facilitating correct association and tracking.
#
# Wrappers included:
# - `_simple_private_task_wrapper`: For simple private tasks (launched via `context.launch_private_process()`).
#   It uses a specific payload format (`SIMPLE_PRIVATE_TASK_RESULT`) for the manager.
# - `_group_member_task_wrapper`: For tasks that are part of a private task group.
#   It uses a specific payload format (`PRIVATE_GROUP_TASK_COMPLETED`) for the manager.
# - `ManagedSharedProcessWrapper`: For managed shared tasks/services.
#   It uses a specific payload format (`SHARED_TASK_RESULT`) for the manager.
#
# Note: The main "ParaProc" wrapper, `LocalParallelizationProcessWrapper`, is defined in 
# `local_parallelization_context.py`, as it is tightly coupled with the context's creation.
# ---


from src_main.tools.logger import loggerRICH


# --- PROCESS WRAPPERS ---

def ManagedSharedProcessWrapper( # Kept name as it's used directly in manager
    shared_task_name: str,
    target_func: callable,
    args: tuple,
    completion_conn_to_manager: typing.Any, # multiprocessing.Connection
    core_to_assign: int | None
):
    log_prefix = f"[ManagedSharedProc '{shared_task_name}']"

    def success_payload(result):
        return {
            'type': 'SHARED_TASK_RESULT', # Distinct type
            'task_name': shared_task_name,
            'status': 'success',
            'result': result
        }

    def exception_payload(ex, tb_str):
        return {
            'type': 'SHARED_TASK_RESULT', # Distinct type
            'task_name': shared_task_name,
            'status': 'exception_in_target',
            'exception_type': type(ex).__name__,
            'exception_message': str(ex),
            'traceback_snippet': tb_str.splitlines()[-3:]
        }
    
    _generic_task_wrapper(
        log_prefix, target_func, args, completion_conn_to_manager, core_to_assign,
        success_payload_transform=success_payload,
        exception_payload_transform=exception_payload
    )

# Wrapper for "simple" private tasks (launched by context.launch_private_process)
